# 1. Add backtest period selector after strategy selector.
marker = '''                        <div>\n                            <label class="block text-xs font-bold text-gray-500 uppercase tracking-widest mb-1">Trading Strategy</label>\n                            <!-- UNLOCKED: Strategy Dropdown -->\n                            <select id="bt-strategy" onchange="toggleBacktestParams()" class="w-full bg-gray-50 border border-gray-200 rounded-lg px-4 py-2 font-bold text-gray-900 outline-none focus:border-teal-500 transition">\n                                <option value="sma_crossover">SMA Crossover (Trend)</option>\n                                <option value="bollinger_bands">Bollinger Bands (Mean Reversion)</option>\n                            </select>\n                        </div>'''
