# 2. Add a second KPI row below the existing three cards.
marker = '''                    </div>\n\n                    <!-- Equity Curve Chart -->'''
extra_kpis = '''                    </div>\n                    <div class="grid grid-cols-3 gap-4 md:gap-6">\n                        <div class="bg-white rounded-2xl shadow-sm border border-gray-200 p-4 md:p-5"><h3 class="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-1">Sharpe Ratio</h3><h1 id="out-bt-sharpe" class="text-2xl font-black text-gray-900">--</h1><p class="text-[10px] text-gray-400 mt-1">Return earned per unit of total volatility.</p></div>\n                        <div class="bg-white rounded-2xl shadow-sm border border-gray-200 p-4 md:p-5"><h3 class="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-1">Sortino Ratio</h3><h1 id="out-bt-sortino" class="text-2xl font-black text-gray-900">--</h1><p class="text-[10px] text-gray-400 mt-1">Return relative to downside volatility only.</p></div>\n                        <div class="bg-white rounded-2xl shadow-sm border border-gray-200 p-4 md:p-5"><h3 class="text-[10px] font-bold text-gray-500 uppercase tracking-widest mb-1">Vs Buy &amp; Hold</h3><h1 id="out-bt-alpha" class="text-2xl font-black text-gray-900">--</h1><p class="text-[10px] text-gray-400 mt-1">Cumulative return difference over this sample.</p></div>\n                    </div>\n\n                    <!-- Equity Curve Chart -->'''
