# 4. Expand existing backtest education modal risk metrics list.
marker = '''            <h4 class="font-bold text-gray-900 uppercase tracking-widest text-[10px] mb-3">Risk Metrics</h4>\n            <ul class="space-y-3 text-sm text-gray-600">\n                <li><strong class="text-gray-900">Max Drawdown:</strong> The largest peak-to-trough drop in the strategy's portfolio value. A critical measure of downside risk.</li>\n                <li><strong class="text-gray-900">Annualised Volatility:</strong> The standard deviation of the strategy's daily returns, scaled to a 252-day trading year to measure the dispersion of returns.</li>\n            </ul>'''
replacement = '''            <h4 class="font-bold text-gray-900 uppercase tracking-widest text-[10px] mb-3">How to judge a backtest</h4>\n            <ul class="space-y-3 text-sm text-gray-600">\n                <li><strong class="text-gray-900">Total Return vs Buy &amp; Hold:</strong> A strategy should be compared with the simple alternative of staying invested. Outperformance is useful context, but not proof of a repeatable edge.</li>\n                <li><strong class="text-gray-900">Sharpe Ratio:</strong> Annualised average strategy return divided by total return volatility. Higher values indicate more return per unit of overall variability.</li>\n                <li><strong class="text-gray-900">Sortino Ratio:</strong> Similar to Sharpe, but only penalises downside volatility. This can be more intuitive when upside volatility is not viewed as harmful.</li>\n                <li><strong class="text-gray-900">Max Drawdown:</strong> The largest peak-to-trough fall in strategy equity. The drawdown chart shows both the depth and duration of periods spent below a previous high.</li>\n                <li><strong class="text-gray-900">Win Rate &amp; Time in Market:</strong> Win rate measures profitable completed position segments; time in market shows how often the strategy was exposed rather than sitting in cash.</li>\n                <li><strong class="text-gray-900">Sample Risk:</strong> A good result over one period can be accidental. Compare different backtest windows and avoid repeatedly tuning parameters until the historical result looks attractive.</li>\n            </ul>'''
if marker not in s:
    raise SystemExit('Backtest education marker not found')
s = s.replace(marker, replacement, 1)

# 5. Send selected period to backend.
marker = '''                const payload = {\n                    ticker: document.getElementById('bt-ticker').value,\n                    strategy: strategy\n                };'''
replacement = '''                const payload = {\n                    ticker: document.getElementById('bt-ticker').value,\n                    strategy: strategy,\n                    period: document.getElementById('bt-period').value\n                };'''
if marker not in s:
    raise SystemExit('Backtest payload marker not found')
s = s.replace(marker, replacement, 1)

# 6. Populate new KPIs after existing ones.
marker = '''                document.getElementById('out-bt-vol').innerText = `${kpis.annualised_volatility}%`; \n                document.getElementById('out-bh-ret').innerText = `Buy & Hold: ${kpis.buy_hold_return > 0 ? '+' : ''}${kpis.buy_hold_return}%`;'''
replacement = '''                document.getElementById('out-bt-vol').innerText = `${kpis.annualised_volatility}%`; \n                document.getElementById('out-bh-ret').innerText = `Buy & Hold: ${kpis.buy_hold_return > 0 ? '+' : ''}${kpis.buy_hold_return}%`;\n                document.getElementById('out-bt-sharpe').innerText = kpis.sharpe_ratio.toFixed(2);\n                document.getElementById('out-bt-sortino').innerText = kpis.sortino_ratio.toFixed(2);\n                const alphaEl = document.getElementById('out-bt-alpha');\n                alphaEl.innerText = `${kpis.excess_return_vs_buy_hold >= 0 ? '+' : ''}${kpis.excess_return_vs_buy_hold.toFixed(2)}%`;\n                alphaEl.className = `text-2xl font-black ${kpis.excess_return_vs_buy_hold >= 0 ? 'text-emerald-600' : 'text-red-600'}`;'''
if marker not in s:
    raise SystemExit('Backtest KPI render marker not found')
s = s.replace(marker, replacement, 1)

