marker = '''                Plotly.newPlot('bt-chart', [\n                    { x: chartData.dates, y: chartData.buy_hold_equity, name: 'Buy & Hold', type: 'scatter', line: {color: '#9ca3af', width: 2, dash: 'dot'} },\n                    { x: chartData.dates, y: chartData.strategy_equity, name: stratName, type: 'scatter', line: {color: '#0d9488', width: 2} }\n                ], {'''
