marker = '''                }, {displayModeBar: false, responsive: true});\n\n            } catch (err) {'''
replacement = '''                }, {displayModeBar: false, responsive: true});\n\n                document.getElementById('backtest-insights').classList.remove('hidden');\n                document.getElementById('out-bt-trades').innerText = kpis.completed_trades;\n                document.getElementById('out-bt-win').innerText = `${kpis.win_rate_pct.toFixed(1)}%`;\n                document.getElementById('out-bt-exposure').innerText = `${kpis.time_in_market_pct.toFixed(1)}%`;\n                document.getElementById('out-bt-worst-dd').innerText = `${kpis.max_drawdown.toFixed(2)}%`;\n\n                Plotly.newPlot('bt-drawdown-chart', [{\n                    x: chartData.dates, y: chartData.drawdown_pct, type: 'scatter', mode: 'lines', fill: 'tozeroy',\n                    line: { color: '#ef4444', width: 2 }, fillcolor: 'rgba(239,68,68,0.10)', name: 'Drawdown',\n                    hovertemplate: '%{x}<br>Drawdown: %{y:.2f}%<extra></extra>'\n                }], {\n                    margin: { t: 15, r: 15, l: 50, b: 40 },\n                    yaxis: { title: 'Drawdown (%)', gridcolor: '#f3f4f6', rangemode: 'tozero' }, xaxis: { showgrid: false },\n                    paper_bgcolor: 'rgba(0,0,0,0)', plot_bgcolor: 'rgba(0,0,0,0)', showlegend: false\n                }, { displayModeBar: false, responsive: true });\n\n                const trades = data.results.trades || [];\n                document.getElementById('bt-trade-table').innerHTML = trades.length ? trades.slice().reverse().map(t => `\n                    <tr class="border-t border-gray-100"><td class="px-4 py-2 text-gray-600">${t.entry_date}</td><td class="px-3 py-2 text-gray-600">${t.exit_date}</td><td class="px-4 py-2 text-right font-black ${t.return_pct >= 0 ? 'text-emerald-600' : 'text-red-600'}">${t.return_pct >= 0 ? '+' : ''}${t.return_pct.toFixed(2)}%</td></tr>`).join('')\n                    : `<tr><td colspan="3" class="text-center text-gray-400 italic py-8">No completed trades in this sample.</td></tr>`;\n\n                const comparison = kpis.excess_return_vs_buy_hold >= 0\n                    ? `The strategy beat buy & hold by ${kpis.excess_return_vs_buy_hold.toFixed(1)} percentage points in this sample.`\n                    : `The strategy lagged buy & hold by ${Math.abs(kpis.excess_return_vs_buy_hold).toFixed(1)} percentage points in this sample.`;\n                const riskRead = kpis.max_drawdown > -15\n                    ? `Its worst drawdown was ${kpis.max_drawdown.toFixed(1)}%, which was relatively contained for this sample.`\n                    : `Its worst drawdown reached ${kpis.max_drawdown.toFixed(1)}%, so total return should not be read without the path of losses.`;\n                document.getElementById('bt-insight-summary').innerText = `${kpis.completed_trades} completed trades · ${kpis.time_in_market_pct.toFixed(1)}% time in market · Sharpe ${kpis.sharpe_ratio.toFixed(2)}.`;\n                document.getElementById('bt-learning-points').innerHTML = `<strong>Interpretation:</strong> ${comparison} ${riskRead} A ${kpis.win_rate_pct.toFixed(1)}% trade win rate does not by itself determine profitability because winning and losing trades can have very different sizes. Try another period before drawing a conclusion.`;\n\n            } catch (err) {'''
